from collections import deque, defaultdict

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    INF = float('inf')

    if grid[0][0] == -1 or grid[R-1][C-1] == -1:
        return -1
    if R == 1 and C == 1:
        return 0

    def bfs(sr, sc):
        dist = [[INF] * C for _ in range(R)]
        dist[sr][sc] = 0
        dq = deque([(sr, sc)])
        while dq:
            r, col = dq.popleft()
            d = dist[r][col] + 1
            if r > 0 and grid[r-1][col] != -1 and dist[r-1][col] == INF:
                dist[r-1][col] = d
                dq.append((r-1, col))
            if r + 1 < R and grid[r+1][col] != -1 and dist[r+1][col] == INF:
                dist[r+1][col] = d
                dq.append((r+1, col))
            if col > 0 and grid[r][col-1] != -1 and dist[r][col-1] == INF:
                dist[r][col-1] = d
                dq.append((r, col-1))
            if col + 1 < C and grid[r][col+1] != -1 and dist[r][col+1] == INF:
                dist[r][col+1] = d
                dq.append((r, col+1))
        return dist

    d_start = bfs(0, 0)
    d_end = bfs(R-1, C-1)

    best = d_start[R-1][C-1]

    # For each label, min distance from start to any cell with that label,
    # and min distance from that label to the end.
    best_from_start = defaultdict(lambda: INF)
    best_to_end = defaultdict(lambda: INF)
    for r in range(R):
        row = grid[r]
        ds = d_start[r]
        de = d_end[r]
        for col in range(C):
            lab = row[col]
            if lab == -1:
                continue
            if ds[col] < best_from_start[lab]:
                best_from_start[lab] = ds[col]
            if de[col] < best_to_end[lab]:
                best_to_end[lab] = de[col]

    # If the two minima come from the same cell, the value is >= the plain
    # walking distance (since c >= 0), so it never wrongly improves the answer.
    for lab, a in best_from_start.items():
        if a == INF:
            continue
        b = best_to_end[lab]
        if b == INF:
            continue
        total = a + c + b
        if total < best:
            best = total

    return -1 if best == INF else best

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("no balanced replacement exists")

    opens = s.count('(')
    qmarks = s.count('?')
    need_open = n // 2 - opens          # number of '?' that must become '('
    if need_open < 0 or need_open > qmarks:
        raise ValueError("no balanced replacement exists")

    # Lexicographically smallest: turn the earliest '?' into '(' as much as allowed.
    # Putting '(' as early as possible also maximizes every prefix balance, so if
    # this assignment is not balanced, no assignment is.
    out = []
    remaining = need_open
    for ch in s:
        if ch == '?':
            if remaining > 0:
                out.append('(')
                remaining -= 1
            else:
                out.append(')')
        else:
            out.append(ch)

    bal = 0
    for ch in out:
        bal += 1 if ch == '(' else -1
        if bal < 0:
            raise ValueError("no balanced replacement exists")
    if bal != 0:
        raise ValueError("no balanced replacement exists")

    return ''.join(out)

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)          # set => duplicate deps collapse to one

    order = []
    visiting = set()   # nodes on the current DFS path (for cycle detection)
    done = set()       # nodes whose entire subtree has been emitted

    def visit(node):
        if node in done:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        done.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

import re

_AMOUNT_RE = re.compile(r"\A([0-9]+)(?:\.([0-9]{1,2}))?\Z")


def _parse_cents(amount):
    """Convert a valid amount string to integer cents exactly, else raise ValueError."""
    if not isinstance(amount, str):
        raise ValueError("amount must be a string")
    m = _AMOUNT_RE.match(amount)
    if m is None:
        raise ValueError(f"invalid amount: {amount!r}")
    whole, frac = m.group(1), m.group(2) or ""
    frac = frac.ljust(2, "0")          # "5" -> "50", "" -> "00"
    cents = int(whole) * 100 + int(frac)
    if cents <= 0:
        raise ValueError("amount must be positive")
    return cents


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        cents = _parse_cents(tx["amount"])
        src, dst = tx["from"], tx["to"]
        balances[src] = balances.get(src, 0) - cents
        balances[dst] = balances.get(dst, 0) + cents
    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])

    # Validate every hunk against the ORIGINAL document before doing anything.
    for start, delete, insert in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    # Conflict detection: identical starts are ambiguous (even for two pure
    # insertions), and delete ranges must not overlap. Touching is allowed.
    for i in range(1, len(ordered)):
        prev_start, prev_delete, _ = ordered[i - 1]
        cur_start = ordered[i][0]
        if cur_start == prev_start or cur_start < prev_start + prev_delete:
            raise ValueError("conflicting hunks")

    # Apply bottom-up so edits never shift the indices of hunks still to come.
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        # Prune expired calls: an admitted call s has expired when t - s >= window.
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        # Admit only if strictly fewer than max_calls are still in the window.
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

class CountingBag:
    """
    A multiset (bag) of hashable items that tracks counts and reports the
    most common items with a deterministic ordering.

    Ordering rule for most_common:
      1. higher count first
      2. ties broken by earlier "entry moment" -- the most recent time the
         item went from absent (count 0) to present (count 1)
    """

    def __init__(self):
        # item -> [count, entry_moment]
        self._data = {}
        self._total = 0
        self._clock = 0  # monotonically increasing; stamps entry moments

    def add(self, item) -> int:
        entry = self._data.get(item)
        if entry is None:
            # item enters the bag now
            self._clock += 1
            self._data[item] = [1, self._clock]
            self._total += 1
            return 1
        entry[0] += 1
        self._total += 1
        return entry[0]

    def discard(self, item) -> bool:
        entry = self._data.get(item)
        if entry is None:
            return False
        entry[0] -= 1
        self._total -= 1
        if entry[0] == 0:
            # item leaves the bag entirely; its entry moment is forgotten
            del self._data[item]
        return True

    def count(self, item) -> int:
        entry = self._data.get(item)
        return entry[0] if entry is not None else 0

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._data)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        ordered = sorted(
            self._data.items(),
            key=lambda kv: (-kv[1][0], kv[1][1]),
        )
        return [(item, cnt_entry[0]) for item, cnt_entry in ordered[:k]]

    def __contains__(self, item) -> bool:
        return item in self._data

    def __repr__(self) -> str:
        return f"CountingBag({self.most_common(len(self._data))!r})"

class Leaderboard:
    """Leaderboard where each player's ranking score is their best submitted score.

    Ties in `top()` are broken by who reached their best earlier (in terms of
    the overall order of *improving* submit calls).
    """

    def __init__(self):
        # player -> (best_score, sequence_number_of_improving_submission)
        self._players = {}
        # monotonically increasing counter for improving submissions
        self._seq = 0

    def submit(self, player, score) -> bool:
        """Record an attempt. Returns True if it improves the player's best."""
        current = self._players.get(player)
        if current is not None and score <= current[0]:
            # Not a strict improvement: change nothing (tie order preserved).
            return False
        self._seq += 1
        self._players[player] = (score, self._seq)
        return True

    def best(self, player) -> int:
        """Return the player's best score. Raises KeyError for unknown players."""
        return self._players[player][0]  # KeyError propagates naturally

    def rank(self, player) -> int:
        """Standard competition ranking: 1 + number of players with strictly greater best."""
        my_best = self._players[player][0]  # KeyError for unknown players
        greater = sum(1 for b, _ in self._players.values() if b > my_best)
        return 1 + greater

    def top(self, k) -> list:
        """Top k players as (player, best) tuples.

        Ordered by best descending; ties ordered by earlier achievement.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        ordered = sorted(
            self._players.items(),
            key=lambda item: (-item[1][0], item[1][1]),
        )
        return [(player, best) for player, (best, _) in ordered[:k]]

    def player_count(self) -> int:
        """Number of distinct players seen."""
        return len(self._players)

