class IntervalSet:
    """
    A set of integers stored as sorted, pairwise-disjoint, non-adjacent
    half-open intervals [lo, hi).

    Invariant (normalized form): for consecutive stored intervals
    (a, b), (c, d) we always have b < c  (strictly less, never touching).
    """

    def __init__(self):
        self._ivs = []  # list of [lo, hi] pairs, kept normalized

    # ------------------------------------------------------------------ #
    # helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _check(lo, hi):
        if not isinstance(lo, int) or not isinstance(hi, int):
            raise TypeError("interval bounds must be integers")
        if lo >= hi:
            raise ValueError(f"invalid interval [{lo}, {hi}): require lo < hi")

    # ------------------------------------------------------------------ #
    # mutation
    # ------------------------------------------------------------------ #
    def add(self, lo, hi):
        """Cover every integer in [lo, hi), merging overlapping/adjacent pieces."""
        self._check(lo, hi)
        new = []
        merged_lo, merged_hi = lo, hi
        placed = False
        for a, b in self._ivs:
            if b < merged_lo:
                # entirely before the new interval, not touching
                new.append((a, b))
            elif a > merged_hi:
                # entirely after the new interval, not touching
                if not placed:
                    new.append((merged_lo, merged_hi))
                    placed = True
                new.append((a, b))
            else:
                # overlaps or touches: absorb it
                merged_lo = min(merged_lo, a)
                merged_hi = max(merged_hi, b)
        if not placed:
            new.append((merged_lo, merged_hi))
        self._ivs = new

    def remove(self, lo, hi):
        """Uncover every integer in [lo, hi)."""
        self._check(lo, hi)
        new = []
        for a, b in self._ivs:
            if b <= lo or a >= hi:
                # no overlap with removal window
                new.append((a, b))
                continue
            # left remainder
            if a < lo:
                new.append((a, lo))
            # right remainder
            if b > hi:
                new.append((hi, b))
        self._ivs = new

    # ------------------------------------------------------------------ #
    # queries
    # ------------------------------------------------------------------ #
    def contains(self, x):
        """Return True if the integer x is covered."""
        # find the last interval whose lo <= x
        idx = bisect_right(self._ivs, (x, float("inf"))) - 1
        if idx < 0:
            return False
        a, b = self._ivs[idx]
        return a <= x < b

    def total(self):
        """Total number of integers covered."""
        return sum(b - a for a, b in self._ivs)

    def intervals(self):
        """Sorted list of (lo, hi) tuples in normalized form."""
        return list(self._ivs)

    def gaps(self, lo, hi):
        """Maximal uncovered sub-intervals of the window [lo, hi)."""
        self._check(lo, hi)
        result = []
        cursor = lo
        for a, b in self._ivs:
            if b <= cursor:
                continue
            if a >= hi:
                break
            if a > cursor:
                result.append((cursor, a))
            cursor = max(cursor, b)
            if cursor >= hi:
                break
        if cursor < hi:
            result.append((cursor, hi))
        return result

    # ------------------------------------------------------------------ #
    # niceties
    # ------------------------------------------------------------------ #
    def __contains__(self, x):
        return self.contains(x)

    def __len__(self):
        return self.total()

    def __repr__(self):
        return f"IntervalSet({self._ivs!r})"

import heapq


class TaskScheduler:
    """
    Priority queue of unique task ids with reprioritization and cancellation.

    Higher priority is served first; ties are broken by original submission
    order (FIFO). Implemented with a binary heap plus lazy deletion:

      * ``_active`` maps task_id -> (priority, seq) for every live task.
      * ``_heap`` holds entries ``(-priority, seq, task_id)``. An entry is
        valid only if ``_active[task_id] == (priority, seq)``; everything
        else is stale and is discarded when it surfaces at the top.
      * ``seq`` is a monotonically increasing counter assigned at submission
        and never changed by reprioritize, which preserves FIFO position.
        A resubmission after pop/cancel gets a fresh seq, so leftovers from
        the previous life of that id can never be mistaken for valid.

    To keep the heap from growing without bound under heavy reprioritize /
    cancel traffic, it is compacted whenever the number of stale entries
    dominates, which keeps every operation O(log n) amortized.
    """

    def __init__(self):
        self._active = {}   # task_id -> (priority, seq)
        self._heap = []     # entries: (-priority, seq, task_id)
        self._seq = 0       # next FIFO sequence number

    # ------------------------------------------------------------------ helpers

    def _is_valid(self, entry):
        neg_pri, seq, task_id = entry
        rec = self._active.get(task_id)
        return rec is not None and rec[0] == -neg_pri and rec[1] == seq

    def _push(self, task_id, priority, seq):
        heapq.heappush(self._heap, (-priority, seq, task_id))
        self._maybe_compact()

    def _maybe_compact(self):
        # Rebuild when stale entries outnumber live ones by a wide margin.
        # Amortized cost is O(1) per operation because a rebuild costing O(m)
        # only happens after ~m/2 pushes since the previous rebuild.
        if len(self._heap) > 64 and len(self._heap) > 2 * len(self._active):
            self._heap = [
                (-pri, seq, tid) for tid, (pri, seq) in self._active.items()
            ]
            heapq.heapify(self._heap)

    def _discard_stale_top(self):
        heap = self._heap
        while heap and not self._is_valid(heap[0]):
            heapq.heappop(heap)

    # --------------------------------------------------------------- interface

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task {task_id!r} is already active")
        seq = self._seq
        self._seq += 1
        self._active[task_id] = (priority, seq)
        self._push(task_id, priority, seq)

    def reprioritize(self, task_id, priority):
        try:
            old_priority, seq = self._active[task_id]
        except KeyError:
            raise KeyError(f"task {task_id!r} is not active") from None
        if priority == old_priority:
            return  # existing heap entry is still exactly right
        self._active[task_id] = (priority, seq)   # old entry becomes stale
        self._push(task_id, priority, seq)        # same seq -> same FIFO slot

    def cancel(self, task_id):
        try:
            del self._active[task_id]   # its heap entry is now stale
        except KeyError:
            raise KeyError(f"task {task_id!r} is not active") from None
        self._maybe_compact()

    def pop(self):
        self._discard_stale_top()
        if not self._heap:
            raise IndexError("pop from empty TaskScheduler")
        _, _, task_id = heapq.heappop(self._heap)
        del self._active[task_id]
        return task_id

    def peek(self):
        self._discard_stale_top()
        if not self._heap:
            raise IndexError("peek from empty TaskScheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        try:
            return self._active[task_id][0]
        except KeyError:
            raise KeyError(f"task {task_id!r} is not active") from None

    def __len__(self):
        return len(self._active)

    def __contains__(self, task_id):
        return task_id in self._active

    def __repr__(self):
        return f"TaskScheduler(active={len(self._active)})"


