    # Stress: compare against a naive reference on a mixed workload
    import random
    random.seed(1)
    ts = TaskScheduler()
    ref = {}   # id -> (priority, seq)
    seq = 0
    for _ in range(100_000):
        op = random.random()
        tid = random.randrange(300)
        if op < 0.4:
            if tid in ref:
                try: ts.submit(tid, 0)
                except ValueError: pass
            else:
                p = random.randrange(-10, 10)
                ts.submit(tid, p); ref[tid] = (p, seq); seq += 1
        elif op < 0.65:
            if tid in ref:
                p = random.randrange(-10, 10)
                ts.reprioritize(tid, p); ref[tid] = (p, ref[tid][1])
        elif op < 0.75:
            if tid in ref:
                ts.cancel(tid); del ref[tid]
        else:
            if ref:
                best = min(ref, key=lambda t: (-ref[t][0], ref[t][1]))
                assert ts.peek() == best
                assert ts.pop() == best
                del ref[best]
        assert len(ts) == len(ref)
    print("all tests passed")

class UndoStack:
    """A LIFO stack whose push/pop operations can be undone."""

    def __init__(self):
        self._items = []
        # History entries: ("push",) or ("pop", value)
        self._history = []

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append(("push",))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty UndoStack")
        value = self._items.pop()
        self._history.append(("pop", value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty UndoStack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        entry = self._history.pop()
        if entry[0] == "push":
            # Reverse a push: remove the value that push added (it is on top).
            self._items.pop()
        else:
            # Reverse a pop: restore the exact popped value to the top.
            self._items.append(entry[1])

    def __len__(self) -> int:
        return len(self._items)

import math


def rank_scores(scores: list) -> list[int]:
    """Assign competition ("1224") ranks to numeric scores; higher is better.

    result[i] = 1 + (number of scores strictly greater than scores[i]).
    Raises ValueError if any score is NaN. Does not mutate the input.
    """
    for s in scores:
        if isinstance(s, float) and math.isnan(s):
            raise ValueError("NaN scores are not allowed")

    if not scores:
        return []

    # Sort a copy in descending order (input is not mutated).
    ordered = sorted(scores, reverse=True)

    # Map each distinct value to its rank: 1 + number of strictly greater scores.
    # Since `ordered` is descending, the first occurrence index of a value equals
    # the count of strictly greater scores. dict keys use ==/hash, so 0.0/-0.0
    # and 2/2.0 collapse to the same key.
    rank_of = {}
    for idx, value in enumerate(ordered):
        if value not in rank_of:
            rank_of[value] = idx + 1

    return [rank_of[s] for s in scores]

def kth_root_floor(n: int, k: int) -> int:
    """
    Return the largest integer r >= 0 such that r ** k <= n.

    Computed exactly using only integer arithmetic (binary search on the
    answer), so it is correct for arbitrarily large n.

    Raises ValueError if n < 0 or k < 1.
    """
    if not isinstance(n, int) or not isinstance(k, int):
        raise TypeError("n and k must be integers")
    if n < 0:
        raise ValueError("n must be nonnegative")
    if k < 1:
        raise ValueError("k must be at least 1")

    if k == 1 or n < 2:
        return n

    # If k >= bit_length(n), then 2**k > n, so the answer is 1.
    bits = n.bit_length()
    if k >= bits:
        return 1

    # The answer r satisfies 2**((bits-1)//k) <= r < 2**(ceil(bits/k)).
    lo = 1 << ((bits - 1) // k)
    hi = 1 << ((bits + k - 1) // k)  # exclusive upper bound

    # Binary search: find largest r in [lo, hi) with r**k <= n.
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid
    return lo

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}

    for i, row in enumerate(rows):
        # a. structure check
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(
                "row {}: expected a tuple of exactly 3 elements".format(i)
            )

        category, amount, refunded = row

        # b. category check
        if not isinstance(category, str) or category == "":
            raise ValueError(
                "row {}: category must be a non-empty str".format(i)
            )

        # c. amount type check (bool explicitly rejected)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(
                "row {}: amount must be an int or float (not bool)".format(i)
            )

        # d. amount value check
        if amount < 0:
            raise ValueError(
                "row {}: amount must be >= 0".format(i)
            )

        # e. refunded check
        if not isinstance(refunded, bool):
            raise TypeError(
                "row {}: refunded must be a bool".format(i)
            )

        amt = float(amount)

        summary = result.get(category)
        if summary is None:
            summary = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": amt,
            }
            result[category] = summary

        summary["count"] += 1
        summary["gross"] += amt
        if not refunded:
            summary["net"] += amt
        if amt > summary["largest"]:
            summary["largest"] = amt

    return result

def clamp_values(values, low, high):
    """
    Return a NEW list with every number in `values` clamped into the
    inclusive range [low, high].

    - values below `low` become `low`
    - values above `high` become `high`
    - everything else is kept unchanged (same object)

    The input list is never mutated, and the returned list is always a
    distinct list object.
    """
    # 1. values must be a list
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    # 2. bounds must be real numbers (int/float), and bool is rejected
    for bound in (low, high):
        if isinstance(bound, bool) or not isinstance(bound, (int, float)):
            raise TypeError("bounds must be numbers")

    # 3. low must not exceed high
    if low > high:
        raise ValueError("low must not exceed high")

    # 4. validate elements in order, reporting the first bad index
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(
                "element at index {} must be a number (int or float), "
                "got {}".format(i, type(item).__name__)
            )

    # Build the clamped result in a brand-new list.
    result = []
    for item in values:
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)  # same object, unchanged
    return result

def render_template(template, context):
    """Render a simple template string using the given context mapping.

    Supported syntax (scanned strictly left to right):
      - "{{" -> literal "{", "}}" -> literal "}"
      - "{name}" -> str(context[name]), name in [A-Za-z0-9_]+
      - anything else is copied through unchanged
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    def is_name_char(ch):
        return (
            ('a' <= ch <= 'z')
            or ('A' <= ch <= 'Z')
            or ('0' <= ch <= '9')
            or ch == '_'
        )

    out = []
    n = len(template)
    i = 0
    while i < n:
        c = template[i]
        if c == '{':
            # Escape detection wins.
            if i + 1 < n and template[i + 1] == '{':
                out.append('{')
                i += 2
                continue
            start = i
            j = i + 1
            while j < n and is_name_char(template[j]):
                j += 1
            if j >= n:
                raise ValueError("unclosed placeholder at position %d" % start)
            if template[j] != '}':
                raise ValueError("invalid placeholder at position %d" % start)
            name = template[start + 1:j]
            if name == '':
                raise ValueError("empty placeholder at position %d" % start)
            if name not in context:
                raise KeyError(name)
            out.append(str(context[name]))
            i = j + 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                out.append('}')
                i += 2
                continue
            raise ValueError("stray '}' at position %d" % i)
        else:
            out.append(c)
            i += 1

    return ''.join(out)

def eval_rpn(tokens):
    """Evaluate a reverse-Polish-notation expression given as a list of strings.

    Operators: "+", "-", "*", "/" ("/" truncates toward zero).
    Operands: optional single leading sign followed by one or more ASCII digits.
    """
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    operators = ("+", "-", "*", "/")
    ascii_digits = "0123456789"

    def is_literal(s):
        # Optional single leading sign, then one or more ASCII digits.
        if not s:
            return False
        body = s
        if body[0] in "+-":
            body = body[1:]
        if not body:
            return False
        for ch in body:
            if ch not in ascii_digits:
                return False
        return True

    def parse_literal(s):
        sign = 1
        body = s
        if body[0] == "-":
            sign = -1
            body = body[1:]
        elif body[0] == "+":
            body = body[1:]
        value = 0
        for ch in body:
            value = value * 10 + (ord(ch) - 48)
        return sign * value

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError("token {} is not a string".format(i))
        if tok in operators:
            if len(stack) < 2:
                raise ValueError("stack underflow at token {}".format(i))
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token {}".format(i))
                stack.append(trunc_div(left, right))
        elif is_literal(tok):
            stack.append(parse_literal(tok))
        else:
            raise ValueError("unknown token {!r} at token {}".format(tok, i))

    if len(stack) != 1:
        raise ValueError("leftover operands: {} values remain on the stack".format(len(stack)))
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("path contains an empty segment")

    return _descend(data, segments)


def _is_int_literal(seg):
    # optional single leading "-", then one or more ASCII digits
    body = seg[1:] if seg.startswith("-") else seg
    return body != "" and body.isascii() and body.isdigit()


def _descend(node, segments):
    # Base case: nothing left to consume -> we've arrived.
    if not segments:
        return node

    seg = segments[0]
    rest = segments[1:]

    if isinstance(node, dict):
        if seg not in node:
            raise KeyError(seg)
        return _descend(node[seg], rest)

    if isinstance(node, list):
        if not _is_int_literal(seg):
            raise ValueError(f"invalid index {seg!r} for list")
        idx = int(seg)
        if idx >= len(node) or idx < -len(node):
            raise IndexError(f"index {seg} out of range")
        return _descend(node[idx], rest)

    raise TypeError(
        f"cannot descend into {type(node).__name__} with segment {seg!r}"
    )

def top_k_frequent(items, k):
    """
    Return (value, count) pairs for the k most frequent distinct values.

    Pairs are ordered by count, descending; ties are broken by first
    occurrence in `items` (earlier value comes first). Ranking is done by
    repeated selection over the distinct values.
    """
    # --- validation, in the required order ---
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    # --- count values, remembering first-occurrence order ---
    counts = {}
    order = []          # distinct values in order of first appearance
    for value in items:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
            order.append(value)

    distinct_total = len(order)
    limit = k if k < distinct_total else distinct_total

    # --- repeated selection ---
    selected = [False] * distinct_total
    result = []
    for _ in range(limit):
        best = -1
        for idx in range(distinct_total):
            if selected[idx]:
                continue
            # Strict '>' keeps the earliest-appearing value on ties,
            # because `order` is already in first-occurrence order.
            if best == -1 or counts[order[idx]] > counts[order[best]]:
                best = idx
        selected[best] = True
        result.append((order[best], counts[order[best]]))

    return result
